import { Download } from 'lucide-react';
import { downloadUrl } from '@/data/api';
import { buttonClasses } from './ui/Button';
import { Icon } from './ui/Icon';

/** Opens the PDF (invoice or receipt) generated by the site. A plain link: works everywhere, even offline later. */
export function DownloadButton({
  kind,
  name,
  label,
  variant = 'subtle',
  fullWidth,
}: {
  kind: 'invoice' | 'receipt';
  name: string;
  label: string;
  variant?: 'solid' | 'subtle' | 'outline';
  fullWidth?: boolean;
}) {
  return (
    <a href={downloadUrl(kind, name)} target="_blank" rel="noopener" className={buttonClasses({ variant, fullWidth })}>
      <Icon icon={Download} />
      {label}
    </a>
  );
}
